INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fe018e84-a1c7-486e-b96e-849e3e13f06b', 'property_casualty', NULL, 'What is Commercial General Liability (CGL) insurance?', '¿Qué es el seguro de Responsabilidad General Comercial (CGL)?', '["Coverage for a business''s liability for bodily injury, property damage, and personal/advertising injury", "Auto insurance for businesses", "Property insurance", "Workers compensation"]', '["Cobertura para la responsabilidad de un negocio por lesiones corporales, daños a la propiedad y lesiones personales/publicitarias", "Seguro de auto para negocios", "Seguro de propiedad", "Compensación de trabajadores"]', 0, 'CGL insurance protects businesses against claims of bodily injury, property damage, and personal/advertising injury to third parties.', 'El seguro CGL protege a los negocios contra reclamos de lesiones corporales, daños a la propiedad y lesiones personales/publicitarias a terceros.', true, '2026-01-14 22:43:34.539488', '2026-01-14 22:43:34.539488') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fe0c9afe-35c2-4716-ae55-00e40c9959c6', 'property_casualty', NULL, 'What is an occurrence trigger in liability insurance?', '¿Qué es un disparador de ocurrencia en seguro de responsabilidad?', '["Coverage is triggered when the bodily injury or property damage occurs", "When the claim is filed", "When the policy is purchased", "When premium is paid"]', '["La cobertura se activa cuando ocurre la lesión corporal o el daño a la propiedad", "Cuando se presenta el reclamo", "Cuando se compra la póliza", "Cuando se paga la prima"]', 0, 'In occurrence-based policies, coverage is triggered by when the injury or damage actually occurred.', 'En pólizas basadas en ocurrencia, la cobertura se activa por cuándo realmente ocurrió la lesión o el daño.', true, '2026-01-14 22:49:00.434443', '2026-01-14 22:49:00.434443') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('001f99cf-9854-4b82-ab25-81366e542355', 'life_insurance', NULL, 'What is the purpose of FINRA in relation to variable life insurance?', '¿Cuál es el propósito de FINRA en relación con el seguro de vida variable?', '["To issue insurance licenses", "To regulate securities aspects of variable products", "To pay claims", "To set premium rates"]', '["Emitir licencias de seguros", "Regular aspectos de valores de productos variables", "Pagar reclamos", "Establecer tasas de primas"]', 1, 'FINRA regulates the securities aspects of variable life insurance, requiring agents to be registered and products to be prospectus-filed.', 'FINRA regula los aspectos de valores del seguro de vida variable, requiriendo que los agentes estén registrados y que los productos tengan prospectos archivados.', true, '2026-01-14 23:06:37.619907', '2026-01-14 23:06:37.619907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('00d8af37-faff-4868-a145-65704b59b3da', 'life_insurance', NULL, 'In Texas, what is the minimum age requirement to obtain a life insurance agent license?', 'En Texas, ¿cuál es el requisito de edad mínima para obtener una licencia de agente de seguros de vida?', '["16 years", "18 years", "21 years", "25 years"]', '["16 años", "18 años", "21 años", "25 años"]', 1, 'Texas requires life insurance agent license applicants to be at least 18 years of age.', 'Texas requiere que los solicitantes de licencia de agente de seguros de vida tengan al menos 18 años de edad.', true, '2026-01-14 23:06:37.489297', '2026-01-14 23:06:37.489297') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('039d4040-8a4c-4ed3-ab14-a967dacab689', 'life_insurance', NULL, 'What is a lump-sum settlement option?', '¿Qué es una opción de liquidación de suma global?', '["The entire death benefit paid in one payment", "Monthly payments", "Annual payments", "Deferred payments"]', '["El beneficio por muerte completo pagado en un solo pago", "Pagos mensuales", "Pagos anuales", "Pagos diferidos"]', 0, 'Lump-sum settlement pays the entire death benefit to the beneficiary in one payment.', 'La liquidación de suma global paga el beneficio por muerte completo al beneficiario en un solo pago.', true, '2026-01-14 22:54:57.393913', '2026-01-14 22:54:57.393913') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('06af5744-91ae-4206-8372-4ffc3bd8f2a8', 'life_insurance', NULL, 'What are policy loans?', '¿Qué son los préstamos de póliza?', '["Loans taken against the cash value of a permanent life insurance policy", "Loans to buy insurance", "Bank loans", "Premium financing"]', '["Préstamos tomados contra el valor en efectivo de una póliza de seguro de vida permanente", "Préstamos para comprar seguro", "Préstamos bancarios", "Financiamiento de primas"]', 0, 'Policy loans allow policyholders to borrow against accumulated cash value at a stated interest rate.', 'Los préstamos de póliza permiten a los asegurados pedir prestado contra el valor en efectivo acumulado a una tasa de interés establecida.', true, '2026-01-14 22:54:57.414028', '2026-01-14 22:54:57.414028') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('07c2c3c2-4597-4cc5-ba3e-681264531115', 'life_insurance', NULL, 'What is a standard risk classification?', '¿Qué es una clasificación de riesgo estándar?', '["A rating for applicants who represent average mortality risk", "Below average risk", "High risk", "Uninsurable"]', '["Una calificación para solicitantes que representan riesgo de mortalidad promedio", "Riesgo por debajo del promedio", "Alto riesgo", "No asegurable"]', 0, 'Standard risk is for applicants with average health and life expectancy who pay standard premium rates.', 'El riesgo estándar es para solicitantes con salud y expectativa de vida promedio que pagan tarifas de prima estándar.', true, '2026-01-14 22:54:57.369626', '2026-01-14 22:54:57.369626') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d3ace5f-4127-4263-b5cd-a65897fa3d5e', 'life_insurance', NULL, 'What is the purpose of the life insurance policy''s incontestability clause?', '¿Cuál es el propósito de la cláusula de incontestabilidad de la póliza de seguro de vida?', '["To allow the insurer to contest claims indefinitely", "To limit the time the insurer can contest a policy based on misrepresentation", "To increase premiums", "To change the death benefit"]', '["Permitir que el asegurador impugne reclamos indefinidamente", "Limitar el tiempo que el asegurador puede impugnar una póliza basándose en tergiversación", "Aumentar las primas", "Cambiar el beneficio por muerte"]', 1, 'The incontestability clause limits the insurer''s right to void a policy based on misrepresentation to a specific period, typically 2 years.', 'La cláusula de incontestabilidad limita el derecho del asegurador de anular una póliza basándose en tergiversación a un período específico, típicamente 2 años.', true, '2026-01-14 23:06:37.534466', '2026-01-14 23:06:37.534466') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0d51dc26-4c2e-4a3a-91c6-c9278ef58d91', 'life_insurance', NULL, 'What is the primary purpose of the life insurance needs analysis?', '¿Cuál es el propósito principal del análisis de necesidades de seguro de vida?', '["To sell the largest policy possible", "To determine the appropriate amount of coverage based on the client''s needs", "To compare insurance companies", "To reduce underwriting requirements"]', '["Vender la póliza más grande posible", "Determinar la cantidad apropiada de cobertura basada en las necesidades del cliente", "Comparar compañías de seguros", "Reducir los requisitos de suscripción"]', 1, 'A needs analysis helps determine the appropriate amount of life insurance coverage based on the client''s financial situation, obligations, and goals.', 'Un análisis de necesidades ayuda a determinar la cantidad apropiada de cobertura de seguro de vida basada en la situación financiera, obligaciones y metas del cliente.', true, '2026-01-14 23:06:37.595607', '2026-01-14 23:06:37.595607') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0dafc35f-422d-4e67-8684-8b966931663d', 'life_insurance', NULL, 'What is the free-look period for life insurance in Texas?', '¿Cuál es el período de revisión gratuita para el seguro de vida en Texas?', '["At least 10 days to review and cancel for a full refund", "30 days", "7 days", "No free-look period"]', '["Al menos 10 días para revisar y cancelar para un reembolso completo", "30 días", "7 días", "Sin período de revisión gratuita"]', 0, 'Texas law provides at least 10 days for policyholders to review a new policy and receive a full refund if cancelled.', 'La ley de Texas proporciona al menos 10 días para que los asegurados revisen una nueva póliza y reciban un reembolso completo si la cancelan.', true, '2026-01-14 22:54:57.296148', '2026-01-14 22:54:57.296148') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0f019f21-f6f1-4fc0-abca-ad421dc0cf0f', 'life_insurance', NULL, 'What is an irrevocable beneficiary?', '¿Qué es un beneficiario irrevocable?', '["A beneficiary who cannot be changed without their consent", "A beneficiary who can be changed anytime", "The insurance company", "The policy owner"]', '["Un beneficiario que no puede cambiarse sin su consentimiento", "Un beneficiario que puede cambiarse en cualquier momento", "La compañía de seguros", "El propietario de la póliza"]', 0, 'An irrevocable beneficiary cannot be changed without the beneficiary''s written consent.', 'Un beneficiario irrevocable no puede cambiarse sin el consentimiento por escrito del beneficiario.', true, '2026-01-14 22:54:57.336258', '2026-01-14 22:54:57.336258') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0f5518b2-2366-469b-9770-39b43ed28bab', 'life_insurance', NULL, 'In Texas, what is required before an agent can sell variable life insurance?', 'En Texas, ¿qué se requiere antes de que un agente pueda vender seguro de vida variable?', '["Only a life insurance license", "A life insurance license and securities registration", "No special requirements", "Only securities registration"]', '["Solo una licencia de seguro de vida", "Una licencia de seguro de vida y registro de valores", "Sin requisitos especiales", "Solo registro de valores"]', 1, 'To sell variable life insurance in Texas, an agent must hold both a life insurance license and be registered with FINRA to sell securities.', 'Para vender seguros de vida variable en Texas, un agente debe tener tanto una licencia de seguro de vida como estar registrado con FINRA para vender valores.', true, '2026-01-14 23:06:37.545258', '2026-01-14 23:06:37.545258') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('0fadb19c-5018-4c1e-ba28-17a91817e9ab', 'life_insurance', NULL, 'What is a long-term care rider?', '¿Qué es un anexo de cuidado a largo plazo?', '["Allows access to death benefit for long-term care expenses", "Increases death benefit", "Reduces premiums", "Changes beneficiary"]', '["Permite acceso al beneficio por muerte para gastos de cuidado a largo plazo", "Aumenta el beneficio por muerte", "Reduce las primas", "Cambia el beneficiario"]', 0, 'A long-term care rider allows the insured to access part of the death benefit to pay for long-term care needs.', 'Un anexo de cuidado a largo plazo permite al asegurado acceder a parte del beneficio por muerte para pagar necesidades de cuidado a largo plazo.', true, '2026-01-14 23:01:15.610485', '2026-01-14 23:01:15.610485') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('12e5e3c2-125e-4477-9511-d7c08838f597', 'life_insurance', NULL, 'What is convertible term life insurance?', '¿Qué es el seguro de vida a término convertible?', '["Term insurance that can be converted to permanent insurance without proof of insurability", "Permanent insurance only", "Non-convertible term", "Health insurance"]', '["Seguro a término que puede convertirse a seguro permanente sin prueba de asegurabilidad", "Solo seguro permanente", "Término no convertible", "Seguro de salud"]', 0, 'Convertible term allows conversion to permanent insurance without a medical exam or underwriting.', 'El término convertible permite conversión a seguro permanente sin examen médico o suscripción.', true, '2026-01-14 22:54:57.275105', '2026-01-14 22:54:57.275105') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1439692f-ae68-46cf-ad9c-561a6a69933c', 'life_insurance', NULL, 'What is the fixed amount settlement option?', '¿Qué es la opción de liquidación de cantidad fija?', '["A specified amount paid periodically until the death benefit is exhausted", "Lump sum", "Interest only", "Indefinite payments"]', '["Una cantidad especificada pagada periódicamente hasta que el beneficio por muerte se agote", "Suma global", "Solo interés", "Pagos indefinidos"]', 0, 'Fixed amount settlement pays a specific dollar amount until the principal and interest are depleted.', 'La liquidación de cantidad fija paga una cantidad de dólares específica hasta que el capital e interés se agoten.', true, '2026-01-14 22:54:57.405376', '2026-01-14 22:54:57.405376') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('144d6f85-0682-4fa0-b41e-31c61c69ef12', 'life_insurance', NULL, 'What is simplified issue life insurance?', '¿Qué es el seguro de vida de emisión simplificada?', '["Life insurance with limited health questions and no medical exam", "Full underwriting required", "Guaranteed issue", "Variable life"]', '["Seguro de vida con preguntas de salud limitadas y sin examen médico", "Suscripción completa requerida", "Emisión garantizada", "Vida variable"]', 0, 'Simplified issue has a short health questionnaire but no physical exam, with faster underwriting.', 'La emisión simplificada tiene un cuestionario de salud corto pero sin examen físico, con suscripción más rápida.', true, '2026-01-14 23:01:15.671323', '2026-01-14 23:01:15.671323') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('17f491ff-bbcc-4e8a-a54a-4e2edbd9fad3', 'life_insurance', NULL, 'What is a variable annuity?', '¿Qué es una anualidad variable?', '["An annuity where payments vary based on investment performance", "Fixed payments", "Guaranteed interest", "No investment component"]', '["Una anualidad donde los pagos varían basándose en el rendimiento de la inversión", "Pagos fijos", "Interés garantizado", "Sin componente de inversión"]', 0, 'Variable annuities have payments that fluctuate based on the performance of underlying investments.', 'Las anualidades variables tienen pagos que fluctúan basándose en el rendimiento de las inversiones subyacentes.', true, '2026-01-14 22:54:57.430969', '2026-01-14 22:54:57.430969') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('17f76270-307e-481a-8f5c-c6aa7d70f630', 'life_insurance', NULL, 'What is the incontestability clause?', '¿Qué es la cláusula de incontestabilidad?', '["A provision preventing the insurer from denying claims after 2 years for misstatements", "A cancellation clause", "A beneficiary provision", "A premium clause"]', '["Una disposición que previene al asegurador de negar reclamos después de 2 años por declaraciones erróneas", "Una cláusula de cancelación", "Una disposición de beneficiario", "Una cláusula de prima"]', 0, 'The incontestability clause prevents insurers from denying claims based on misrepresentations in the application after 2 years.', 'La cláusula de incontestabilidad previene a los aseguradores de negar reclamos basados en declaraciones erróneas en la solicitud después de 2 años.', true, '2026-01-14 18:28:35.653432', '2026-01-14 18:28:35.653432') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('18530c44-f647-464f-a6ac-30568ab76924', 'life_insurance', NULL, 'What is juvenile life insurance?', '¿Qué es el seguro de vida juvenil?', '["Life insurance purchased on a child''s life", "Adult insurance only", "Health insurance for children", "Property insurance"]', '["Seguro de vida comprado sobre la vida de un niño", "Solo seguro de adultos", "Seguro de salud para niños", "Seguro de propiedad"]', 0, 'Juvenile life insurance is purchased on a child''s life, often by parents or grandparents.', 'El seguro de vida juvenil se compra sobre la vida de un niño, a menudo por padres o abuelos.', true, '2026-01-14 23:01:15.702698', '2026-01-14 23:01:15.702698') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1877512e-aec0-4406-9ae1-650021d27c80', 'life_insurance', NULL, 'What is disability income insurance?', '¿Qué es el seguro de ingreso por discapacidad?', '["Insurance that replaces income if you become unable to work due to illness or injury", "Life insurance", "Health insurance", "Property insurance"]', '["Seguro que reemplaza ingresos si te vuelves incapaz de trabajar debido a enfermedad o lesión", "Seguro de vida", "Seguro de salud", "Seguro de propiedad"]', 0, 'Disability income insurance provides a portion of your income if you become disabled and cannot work.', 'El seguro de ingreso por discapacidad proporciona una porción de tu ingreso si quedas discapacitado y no puedes trabajar.', true, '2026-01-14 18:28:35.661563', '2026-01-14 18:28:35.661563') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1ab8dc46-65f1-4715-8cf1-f062e763afc2', 'life_insurance', NULL, 'What is single premium life insurance?', '¿Qué es el seguro de vida de prima única?', '["Life insurance purchased with one lump-sum payment", "Monthly premium insurance", "Annual premium insurance", "No premium insurance"]', '["Seguro de vida comprado con un pago único de suma global", "Seguro de prima mensual", "Seguro de prima anual", "Seguro sin prima"]', 0, 'Single premium life insurance is paid for with one upfront lump-sum payment.', 'El seguro de vida de prima única se paga con un pago único por adelantado de suma global.', true, '2026-01-14 22:54:57.278703', '2026-01-14 22:54:57.278703') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1b06127d-4edd-46d7-aa8a-277aea0b47f8', 'life_insurance', NULL, 'What is whole life insurance?', '¿Qué es el seguro de vida entera?', '["Permanent life insurance with level premiums and cash value accumulation", "Temporary insurance", "Health insurance", "Auto insurance"]', '["Seguro de vida permanente con primas niveladas y acumulación de valor en efectivo", "Seguro temporal", "Seguro de salud", "Seguro de auto"]', 0, 'Whole life insurance provides lifetime coverage with fixed premiums and builds cash value over time.', 'El seguro de vida entera proporciona cobertura de por vida con primas fijas y acumula valor en efectivo con el tiempo.', true, '2026-01-14 22:54:57.222104', '2026-01-14 22:54:57.222104') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1bfbab19-683e-447f-bfca-7fe26c64ec4b', 'life_insurance', NULL, 'What is the annuity period (annuitization)?', '¿Qué es el período de anualidad (anualización)?', '["The payout phase when periodic payments are made to the annuitant", "The accumulation phase", "The surrender period", "The application period"]', '["La fase de pago cuando se hacen pagos periódicos al beneficiario", "La fase de acumulación", "El período de rescate", "El período de solicitud"]', 0, 'The annuity period is when the accumulated value is converted to periodic income payments.', 'El período de anualidad es cuando el valor acumulado se convierte en pagos de ingreso periódicos.', true, '2026-01-14 22:54:57.449449', '2026-01-14 22:54:57.449449') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1d8c1e99-faa2-4be9-beb3-223c9160b874', 'life_insurance', NULL, 'What is the contestability period?', '¿Qué es el período de contestabilidad?', '["The first 2 years when insurers can investigate and deny claims for misrepresentation", "The grace period", "The free look period", "The waiting period"]', '["Los primeros 2 años cuando los aseguradores pueden investigar y negar reclamos por tergiversación", "El período de gracia", "El período de revisión gratuita", "El período de espera"]', 0, 'The contestability period is typically the first 2 years of a policy during which the insurer can investigate and deny claims for misrepresentation.', 'El período de contestabilidad es típicamente los primeros 2 años de una póliza durante los cuales el asegurador puede investigar y negar reclamos por tergiversación.', true, '2026-01-14 18:28:35.658907', '2026-01-14 18:28:35.658907') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1e09e213-5b4c-4ac3-a009-fbee61e4dc80', 'life_insurance', NULL, 'What is a joint and survivor annuity?', '¿Qué es una anualidad conjunta y de sobreviviente?', '["An annuity that pays income for the lives of two people", "Single life only", "Fixed period only", "Lump sum only"]', '["Una anualidad que paga ingreso por las vidas de dos personas", "Solo vida única", "Solo período fijo", "Solo suma global"]', 0, 'Joint and survivor annuity provides payments during both annuitants'' lives, continuing after the first death.', 'La anualidad conjunta y de sobreviviente proporciona pagos durante las vidas de ambos beneficiarios, continuando después de la primera muerte.', true, '2026-01-14 22:54:57.455092', '2026-01-14 22:54:57.455092') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1f49a0e1-3015-4c70-8eee-7179cc1416a3', 'life_insurance', NULL, 'In Texas, what is the standard free look period for life insurance policies?', 'En Texas, ¿cuál es el período estándar de revisión gratuita para pólizas de seguro de vida?', '["5 days", "10 days", "20 days", "30 days"]', '["5 días", "10 días", "20 días", "30 días"]', 2, 'Texas provides a 20-day free look period for life insurance policies, allowing the policyholder to return the policy for a full refund.', 'Texas proporciona un período de revisión gratuita de 20 días para pólizas de seguro de vida, permitiendo al titular de la póliza devolver la póliza para un reembolso completo.', true, '2026-01-14 23:06:37.587771', '2026-01-14 23:06:37.587771') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('1fa6e17e-8963-4be5-95ae-7e41666c1666', 'life_insurance', NULL, 'What is a beneficiary?', '¿Qué es un beneficiario?', '["The person or entity designated to receive the death benefit", "The insured", "The insurance agent", "The insurance company"]', '["La persona o entidad designada para recibir el beneficio por muerte", "El asegurado", "El agente de seguros", "La compañía de seguros"]', 0, 'A beneficiary is the person or entity named to receive the death benefit when the insured dies.', 'Un beneficiario es la persona o entidad nombrada para recibir el beneficio por muerte cuando el asegurado fallece.', true, '2026-01-14 22:54:57.324888', '2026-01-14 22:54:57.324888') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('201a7c6a-8920-4990-95d7-0fd19bb93d08', 'life_insurance', NULL, 'How often must a Texas life insurance license be renewed?', '¿Con qué frecuencia debe renovarse una licencia de seguro de vida de Texas?', '["Every 2 years", "Every year", "Every 3 years", "Every 5 years"]', '["Cada 2 años", "Cada año", "Cada 3 años", "Cada 5 años"]', 0, 'Texas insurance licenses must be renewed every two years.', 'Las licencias de seguros de Texas deben renovarse cada dos años.', true, '2026-01-14 22:54:57.191697', '2026-01-14 22:54:57.191697') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2154c63e-cbf5-4034-8dc1-b11f7128d5db', 'life_insurance', NULL, 'What is extended term insurance as a nonforfeiture option?', '¿Qué es el seguro a término extendido como opción de no caducidad?', '["Using cash value to purchase term insurance for the same face amount", "Reduced paid-up insurance", "Cash surrender", "Automatic premium loan"]', '["Usar el valor en efectivo para comprar seguro a término por el mismo monto nominal", "Seguro reducido pagado", "Rescate en efectivo", "Préstamo automático de prima"]', 0, 'Extended term uses the cash value to buy term insurance for the full face amount for as long as the cash value allows.', 'El término extendido usa el valor en efectivo para comprar seguro a término por el monto nominal completo por el tiempo que el valor en efectivo permita.', true, '2026-01-14 23:01:15.542521', '2026-01-14 23:01:15.542521') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('21cbb1f3-864e-48ba-abdb-d16be8854437', 'life_insurance', NULL, 'What is the Medical Information Bureau (MIB)?', '¿Qué es la Oficina de Información Médica (MIB)?', '["An organization that shares medical underwriting information among insurers", "A government agency", "A hospital network", "An insurance company"]', '["Una organización que comparte información de suscripción médica entre aseguradores", "Una agencia del gobierno", "Una red de hospitales", "Una compañía de seguros"]', 0, 'The MIB is a nonprofit that helps insurers detect fraud by sharing relevant medical underwriting information.', 'El MIB es una organización sin fines de lucro que ayuda a los aseguradores a detectar fraude compartiendo información relevante de suscripción médica.', true, '2026-01-14 22:54:57.390024', '2026-01-14 22:54:57.390024') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('21d2890c-1ac3-4f20-8d9c-a2eba6f509bc', 'life_insurance', NULL, 'What is the accidental death benefit rider?', '¿Qué es el anexo de beneficio por muerte accidental?', '["Provides additional death benefit if death results from an accident", "Reduces death benefit", "Provides health coverage", "Reduces premiums"]', '["Proporciona beneficio por muerte adicional si la muerte resulta de un accidente", "Reduce el beneficio por muerte", "Proporciona cobertura de salud", "Reduce las primas"]', 0, 'The accidental death benefit (double indemnity) rider pays an additional amount if death is caused by an accident.', 'El anexo de beneficio por muerte accidental (doble indemnización) paga una cantidad adicional si la muerte es causada por un accidente.', true, '2026-01-14 22:54:57.354825', '2026-01-14 22:54:57.354825') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('22357ded-6260-4ea6-9132-7876cbd2901f', 'life_insurance', NULL, 'What is renewable term life insurance?', '¿Qué es el seguro de vida a término renovable?', '["Term insurance that can be renewed at the end of the term without proof of insurability", "One-time coverage only", "Permanent coverage", "Coverage that cannot be renewed"]', '["Seguro a término que puede renovarse al final del término sin prueba de asegurabilidad", "Solo cobertura única", "Cobertura permanente", "Cobertura que no puede renovarse"]', 0, 'Renewable term allows the policyholder to renew coverage at the end of the term without medical underwriting.', 'El término renovable permite al asegurado renovar la cobertura al final del término sin suscripción médica.', true, '2026-01-14 22:54:57.270919', '2026-01-14 22:54:57.270919') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('247baf52-51e5-4c67-b072-0e05b9eec66c', 'life_insurance', NULL, 'What is a buy-sell agreement funded with life insurance?', '¿Qué es un acuerdo de compra-venta financiado con seguro de vida?', '["An agreement to transfer business ownership upon an owner''s death, funded by life insurance", "A sales contract", "A property deed", "A loan agreement"]', '["Un acuerdo para transferir la propiedad del negocio al fallecer un propietario, financiado por seguro de vida", "Un contrato de ventas", "Una escritura de propiedad", "Un acuerdo de préstamo"]', 0, 'Buy-sell agreements use life insurance to fund the purchase of a deceased owner''s business interest.', 'Los acuerdos de compra-venta usan seguro de vida para financiar la compra del interés comercial de un propietario fallecido.', true, '2026-01-14 22:54:57.487654', '2026-01-14 22:54:57.487654') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('24b47ae7-ee30-45df-ae3b-ef77e6cc214b', 'life_insurance', NULL, 'What is the cost basis in a life insurance policy?', '¿Cuál es la base de costo en una póliza de seguro de vida?', '["The death benefit amount", "The total premiums paid into the policy", "The cash value", "The face amount"]', '["El monto del beneficio por muerte", "El total de primas pagadas en la póliza", "El valor en efectivo", "El monto nominal"]', 1, 'The cost basis is the total amount of premiums paid into a life insurance policy, used to determine taxable gains on surrenders or withdrawals.', 'La base de costo es el monto total de primas pagadas en una póliza de seguro de vida, utilizado para determinar las ganancias imponibles en rescates o retiros.', true, '2026-01-14 23:06:37.553005', '2026-01-14 23:06:37.553005') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('257a4fbc-b432-46ee-b3b2-52f220f2e047', 'life_insurance', NULL, 'What is joint life insurance?', '¿Qué es el seguro de vida conjunto?', '["A single policy covering two lives, paying on the first death", "Individual policies", "Group insurance", "No death benefit"]', '["Una sola póliza que cubre dos vidas, pagando en la primera muerte", "Pólizas individuales", "Seguro grupal", "Sin beneficio por muerte"]', 0, 'Joint life (first-to-die) insurance covers two people and pays the death benefit when the first insured dies.', 'El seguro de vida conjunto (primero en morir) cubre a dos personas y paga el beneficio por muerte cuando el primer asegurado fallece.', true, '2026-01-14 23:01:15.653279', '2026-01-14 23:01:15.653279') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('287af7b5-6be0-4632-b5d7-adef29ef87a1', 'life_insurance', NULL, 'What is family maintenance policy?', '¿Qué es una póliza de mantenimiento familiar?', '["Provides monthly income for a set period following the insured''s death, then lump sum", "Lump sum only", "Income only", "No death benefit"]', '["Proporciona ingreso mensual por un período establecido después de la muerte del asegurado, luego suma global", "Solo suma global", "Solo ingreso", "Sin beneficio por muerte"]', 0, 'Family maintenance policy provides income for a fixed period after death, then pays the full face amount.', 'La póliza de mantenimiento familiar proporciona ingreso por un período fijo después de la muerte, luego paga el monto nominal completo.', true, '2026-01-14 23:01:15.697646', '2026-01-14 23:01:15.697646') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2b61aa84-8f47-458f-97f9-55e5c5d8b5e4', 'life_insurance', NULL, 'What is the purpose of an accelerated death benefit rider?', '¿Cuál es el propósito de un anexo de beneficio por muerte acelerada?', '["To increase the death benefit", "To allow early access to death benefit for terminally ill insureds", "To reduce premiums", "To add additional insureds"]', '["Aumentar el beneficio por muerte", "Permitir acceso anticipado al beneficio por muerte para asegurados con enfermedad terminal", "Reducir las primas", "Agregar asegurados adicionales"]', 1, 'An accelerated death benefit rider allows terminally ill policyholders to receive a portion of the death benefit while still living.', 'Un anexo de beneficio por muerte acelerada permite a los titulares de pólizas con enfermedades terminales recibir una porción del beneficio por muerte mientras aún viven.', true, '2026-01-14 23:06:37.495445', '2026-01-14 23:06:37.495445') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2c247b87-e5d6-4a7b-b92b-66909d90f781', 'life_insurance', NULL, 'Are life insurance dividends taxable?', '¿Son gravables los dividendos del seguro de vida?', '["Generally no, they are considered a return of premium", "Yes, fully taxable", "Taxed as capital gains", "Taxed as interest income"]', '["Generalmente no, se consideran una devolución de prima", "Sí, totalmente gravables", "Gravados como ganancias de capital", "Gravados como ingresos por intereses"]', 0, 'Policy dividends are generally not taxable because they''re considered a return of overpaid premiums.', 'Los dividendos de póliza generalmente no son gravables porque se consideran una devolución de primas pagadas en exceso.', true, '2026-01-14 23:01:15.636168', '2026-01-14 23:01:15.636168') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2d24abee-a1d5-471e-a4f4-f50483abdd8d', 'life_insurance', NULL, 'What type of life insurance provides coverage for a specific period and has no cash value?', '¿Qué tipo de seguro de vida proporciona cobertura por un período específico y no tiene valor en efectivo?', '["Whole life", "Universal life", "Term life", "Variable life"]', '["Vida entera", "Vida universal", "Vida a término", "Vida variable"]', 2, 'Term life insurance provides coverage for a specific period (term) and does not accumulate cash value.', 'El seguro de vida a término proporciona cobertura por un período específico (término) y no acumula valor en efectivo.', true, '2026-01-14 23:06:37.505176', '2026-01-14 23:06:37.505176') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2e29bd16-737f-4c74-97a5-5df0131980c5', 'life_insurance', NULL, 'What is a qualified annuity?', '¿Qué es una anualidad calificada?', '["An annuity funded with pre-tax dollars as part of a qualified retirement plan", "Post-tax funded", "Not for retirement", "Individual policy only"]', '["Una anualidad financiada con dólares antes de impuestos como parte de un plan de jubilación calificado", "Financiada después de impuestos", "No para jubilación", "Solo póliza individual"]', 0, 'A qualified annuity is funded with pre-tax dollars and is subject to retirement plan rules and taxation.', 'Una anualidad calificada se financia con dólares antes de impuestos y está sujeta a reglas de planes de jubilación y tributación.', true, '2026-01-14 23:01:15.775694', '2026-01-14 23:01:15.775694') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2ee85687-c9d0-4e59-953b-2cc5bbed4a28', 'life_insurance', NULL, 'What is the assignment provision?', '¿Qué es la disposición de cesión?', '["Allows the policy owner to transfer ownership rights to another party", "Prevents any transfers", "Changes the insured", "Cancels the policy"]', '["Permite al propietario de la póliza transferir derechos de propiedad a otra parte", "Previene cualquier transferencia", "Cambia al asegurado", "Cancela la póliza"]', 0, 'The assignment provision allows the policy owner to transfer some or all policy rights to another person or entity.', 'La disposición de cesión permite al propietario de la póliza transferir algunos o todos los derechos de la póliza a otra persona o entidad.', true, '2026-01-14 23:01:15.562125', '2026-01-14 23:01:15.562125') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('2f329ffd-d730-44e0-a1c2-f5915eefbe2e', 'life_insurance', NULL, 'What is the aviation exclusion?', '¿Qué es la exclusión de aviación?', '["Excludes death benefits if death occurs during certain aviation activities", "Covers all aviation deaths", "Increases benefits for pilots", "No effect on coverage"]', '["Excluye beneficios por muerte si la muerte ocurre durante ciertas actividades de aviación", "Cubre todas las muertes de aviación", "Aumenta beneficios para pilotos", "Sin efecto en la cobertura"]', 0, 'The aviation exclusion may exclude or limit benefits if death results from certain flying activities.', 'La exclusión de aviación puede excluir o limitar beneficios si la muerte resulta de ciertas actividades de vuelo.', true, '2026-01-14 23:01:15.586298', '2026-01-14 23:01:15.586298') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('343aebf3-d559-4958-b3b4-c88e88890fc0', 'life_insurance', NULL, 'What is a cross-purchase buy-sell agreement?', '¿Qué es un acuerdo de compra cruzada de compra-venta?', '["Each owner buys insurance on the other owners to fund the purchase of their interest", "The business buys insurance", "No insurance involved", "Bank financing only"]', '["Cada propietario compra seguro sobre los otros propietarios para financiar la compra de su interés", "El negocio compra seguro", "Sin seguro involucrado", "Solo financiamiento bancario"]', 0, 'In cross-purchase agreements, business owners insure each other and use proceeds to buy a deceased owner''s share.', 'En acuerdos de compra cruzada, los propietarios del negocio aseguran a cada uno y usan los beneficios para comprar la parte de un propietario fallecido.', true, '2026-01-14 22:54:57.490339', '2026-01-14 22:54:57.490339') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('36a2c72d-250a-45d3-89f6-e739e0cba74b', 'life_insurance', NULL, 'What is a Modified Endowment Contract (MEC)?', '¿Qué es un Contrato de Dotación Modificado (MEC)?', '["A life insurance policy that fails the 7-pay test and has less favorable tax treatment", "A standard policy", "A health policy", "A term policy"]', '["Una póliza de seguro de vida que no pasa la prueba de 7 pagos y tiene tratamiento fiscal menos favorable", "Una póliza estándar", "Una póliza de salud", "Una póliza a término"]', 0, 'A MEC is a policy funded too quickly that loses some tax advantages; withdrawals may be taxable and penalized.', 'Un MEC es una póliza financiada demasiado rápido que pierde algunas ventajas fiscales; los retiros pueden ser gravables y penalizados.', true, '2026-01-14 22:54:57.47951', '2026-01-14 22:54:57.47951') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('38b216f0-7325-419c-b28a-85f21cb0ea0f', 'life_insurance', NULL, 'What is term life insurance?', '¿Qué es el seguro de vida a término?', '["Life insurance that provides coverage for a specific period of time", "Permanent life insurance", "Investment insurance", "Health insurance"]', '["Seguro de vida que proporciona cobertura por un período específico de tiempo", "Seguro de vida permanente", "Seguro de inversión", "Seguro de salud"]', 0, 'Term life insurance provides death benefit protection for a specified term, such as 10, 20, or 30 years.', 'El seguro de vida a término proporciona protección de beneficio por muerte por un término especificado, como 10, 20 o 30 años.', true, '2026-01-14 22:54:57.218375', '2026-01-14 22:54:57.218375') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3aaa2145-1367-4417-846a-1ea260f672ae', 'life_insurance', NULL, 'What is split-dollar life insurance?', '¿Qué es el seguro de vida de dólar dividido?', '["An arrangement where employer and employee share premium costs and death benefits", "Standard group insurance", "Individual insurance only", "Health insurance"]', '["Un arreglo donde el empleador y el empleado comparten costos de prima y beneficios por muerte", "Seguro grupal estándar", "Solo seguro individual", "Seguro de salud"]', 0, 'Split-dollar involves sharing premium costs and benefits between an employer and employee.', 'El dólar dividido involucra compartir costos de prima y beneficios entre un empleador y un empleado.', true, '2026-01-14 22:54:57.496224', '2026-01-14 22:54:57.496224') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3b56aa54-edc7-4ca9-85ae-0f231a617cb8', 'life_insurance', NULL, 'What is a child term rider?', '¿Qué es un anexo de término infantil?', '["Provides term insurance coverage on all children of the insured", "Only covers one child", "Permanent coverage for children", "No coverage for children"]', '["Proporciona cobertura de seguro a término para todos los hijos del asegurado", "Solo cubre a un hijo", "Cobertura permanente para hijos", "Sin cobertura para hijos"]', 0, 'A child term rider provides term life coverage for all eligible children of the policyholder.', 'Un anexo de término infantil proporciona cobertura de vida a término para todos los hijos elegibles del asegurado.', true, '2026-01-14 23:01:15.60591', '2026-01-14 23:01:15.60591') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3ceb6fb9-b3f4-464d-b7d3-dfcc5dcd3147', 'life_insurance', NULL, 'What is the difference between a revocable and irrevocable beneficiary?', '¿Cuál es la diferencia entre un beneficiario revocable e irrevocable?', '["No difference", "Revocable can be changed; irrevocable cannot be changed without consent", "Irrevocable receives more money", "Revocable must be a family member"]', '["Sin diferencia", "El revocable se puede cambiar; el irrevocable no se puede cambiar sin consentimiento", "El irrevocable recibe más dinero", "El revocable debe ser un familiar"]', 1, 'A revocable beneficiary can be changed by the policyholder at any time, while an irrevocable beneficiary cannot be changed without that beneficiary''s consent.', 'Un beneficiario revocable puede ser cambiado por el titular de la póliza en cualquier momento, mientras que un beneficiario irrevocable no puede ser cambiado sin el consentimiento de ese beneficiario.', true, '2026-01-14 23:06:37.531177', '2026-01-14 23:06:37.531177') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3e0811e6-0d0b-45f0-9f9e-88bde762c109', 'life_insurance', NULL, 'What is the 7-pay test?', '¿Qué es la prueba de 7 pagos?', '["A test to determine if a policy is a MEC based on premium limits over 7 years", "A health test", "An income test", "A mortality test"]', '["Una prueba para determinar si una póliza es un MEC basada en límites de prima durante 7 años", "Una prueba de salud", "Una prueba de ingresos", "Una prueba de mortalidad"]', 0, 'The 7-pay test determines if premiums paid exceed what would fund the policy in 7 level payments.', 'La prueba de 7 pagos determina si las primas pagadas exceden lo que financiaría la póliza en 7 pagos nivelados.', true, '2026-01-14 22:54:57.482221', '2026-01-14 22:54:57.482221') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f30230f-2113-42c7-a685-023741c3ca5a', 'life_insurance', NULL, 'What is the reinstatement provision?', '¿Qué es la disposición de reinstalación?', '["Allows a lapsed policy to be restored within a certain period", "Automatic renewal", "Policy cancellation", "Premium waiver"]', '["Permite que una póliza caducada se restaure dentro de un cierto período", "Renovación automática", "Cancelación de póliza", "Exención de prima"]', 0, 'Reinstatement allows policyholders to restore lapsed coverage by paying back premiums and proving insurability.', 'La reinstalación permite a los asegurados restaurar cobertura caducada pagando primas atrasadas y probando asegurabilidad.', true, '2026-01-14 22:54:57.320398', '2026-01-14 22:54:57.320398') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('3f745841-962f-46ec-b7cd-fd66e1b98f91', 'life_insurance', NULL, 'What is the suicide clause?', '¿Qué es la cláusula de suicidio?', '["A provision limiting death benefits if the insured commits suicide within a specified period (usually 2 years)", "Full benefits always paid", "No exclusion for suicide", "Benefits doubled for suicide"]', '["Una disposición que limita los beneficios por muerte si el asegurado comete suicidio dentro de un período especificado (usualmente 2 años)", "Beneficios completos siempre pagados", "Sin exclusión por suicidio", "Beneficios duplicados por suicidio"]', 0, 'The suicide clause limits benefits to premium refund if death by suicide occurs within the first two years.', 'La cláusula de suicidio limita los beneficios al reembolso de primas si la muerte por suicidio ocurre dentro de los primeros dos años.', true, '2026-01-14 22:54:57.313034', '2026-01-14 22:54:57.313034') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('40db72d8-8894-47d9-92eb-a82ea12e2ca1', 'life_insurance', NULL, 'What is a viatical settlement?', '¿Qué es un acuerdo viático?', '["Selling a life insurance policy for a lump sum to a third party, typically by someone terminally ill", "A premium payment", "A policy loan", "A claim payment"]', '["Vender una póliza de seguro de vida por una suma global a un tercero, típicamente por alguien terminalmente enfermo", "Un pago de prima", "Un préstamo de póliza", "Un pago de reclamo"]', 0, 'A viatical settlement allows a terminally ill person to sell their life insurance policy for immediate cash.', 'Un acuerdo viático permite a una persona terminalmente enferma vender su póliza de seguro de vida por efectivo inmediato.', true, '2026-01-14 22:54:57.501108', '2026-01-14 22:54:57.501108') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('414e7fa1-8c7e-4f59-91bc-51117e6c5c4d', 'life_insurance', NULL, 'What is the purpose of the insurance company''s annual statement?', '¿Cuál es el propósito de la declaración anual de la compañía de seguros?', '["To advertise products", "To report the company''s financial condition to regulators", "To pay dividends", "To issue new policies"]', '["Publicitar productos", "Informar la condición financiera de la compañía a los reguladores", "Pagar dividendos", "Emitir nuevas pólizas"]', 1, 'The annual statement reports the insurance company''s financial condition to state regulators and is filed with the Texas Department of Insurance.', 'La declaración anual informa la condición financiera de la compañía de seguros a los reguladores estatales y se presenta ante el Departamento de Seguros de Texas.', true, '2026-01-14 23:06:37.613078', '2026-01-14 23:06:37.613078') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('41621cec-4623-4788-b241-5c8abe0aef23', 'life_insurance', NULL, 'What is a single premium annuity?', '¿Qué es una anualidad de prima única?', '["An annuity funded with one lump-sum payment", "Monthly premiums", "Annual premiums", "No premium required"]', '["Una anualidad financiada con un pago único de suma global", "Primas mensuales", "Primas anuales", "Sin prima requerida"]', 0, 'A single premium annuity is purchased with one lump-sum payment.', 'Una anualidad de prima única se compra con un pago único de suma global.', true, '2026-01-14 22:54:57.439982', '2026-01-14 22:54:57.439982') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4409c2b3-3420-45df-bdc8-8c8612ea09a0', 'life_insurance', NULL, 'What is a participating policy?', '¿Qué es una póliza participante?', '["A policy that pays dividends to policyholders", "A non-dividend policy", "A term policy only", "A variable policy"]', '["Una póliza que paga dividendos a los asegurados", "Una póliza sin dividendos", "Solo una póliza a término", "Una póliza variable"]', 0, 'A participating policy shares in the insurer''s surplus by paying policy dividends to owners.', 'Una póliza participante comparte el excedente del asegurador pagando dividendos de póliza a los propietarios.', true, '2026-01-14 23:01:15.631655', '2026-01-14 23:01:15.631655') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('462299b1-b385-4ea4-845f-1e6902b7a427', 'life_insurance', NULL, 'What state agency regulates life insurance in Texas?', '¿Qué agencia estatal regula el seguro de vida en Texas?', '["Texas Department of Insurance (TDI)", "Texas Real Estate Commission", "Texas Department of Health", "Texas Banking Commission"]', '["Departamento de Seguros de Texas (TDI)", "Comisión de Bienes Raíces de Texas", "Departamento de Salud de Texas", "Comisión Bancaria de Texas"]', 0, 'The Texas Department of Insurance (TDI) regulates all types of insurance in Texas, including life insurance.', 'El Departamento de Seguros de Texas (TDI) regula todos los tipos de seguros en Texas, incluyendo el seguro de vida.', true, '2026-01-14 22:54:57.175254', '2026-01-14 22:54:57.175254') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('46e804dd-2e04-4928-b8b4-5c1ff072198a', 'life_insurance', NULL, 'What is a beneficiary in life insurance?', '¿Qué es un beneficiario en seguro de vida?', '["The person or entity who receives the death benefit", "The insurance agent", "The insured person", "The insurance company"]', '["La persona o entidad que recibe el beneficio por muerte", "El agente de seguros", "La persona asegurada", "La compañía de seguros"]', 0, 'A beneficiary is the person, organization, or trust named to receive the life insurance death benefit upon the insured''s death.', 'Un beneficiario es la persona, organización o fideicomiso nombrado para recibir el beneficio por muerte del seguro de vida tras la muerte del asegurado.', true, '2026-01-14 18:28:35.642863', '2026-01-14 18:28:35.642863') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4754b034-a37d-4169-b5a8-9ed1d06278c4', 'life_insurance', NULL, 'What is long-term care insurance?', '¿Qué es el seguro de cuidados a largo plazo?', '["Insurance covering extended care services not covered by health insurance", "Life insurance", "Disability insurance", "Auto insurance"]', '["Seguro que cubre servicios de cuidado extendido no cubiertos por seguro de salud", "Seguro de vida", "Seguro de discapacidad", "Seguro de auto"]', 0, 'Long-term care insurance covers costs of care for chronic illness, disability, or aging that are not covered by regular health insurance.', 'El seguro de cuidados a largo plazo cubre costos de cuidado para enfermedades crónicas, discapacidad o envejecimiento que no están cubiertos por seguro de salud regular.', true, '2026-01-14 18:28:35.664321', '2026-01-14 18:28:35.664321') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('47a37e4b-d4e1-4c5d-a5cb-42fc8e1dbd97', 'life_insurance', NULL, 'What is an absolute assignment?', '¿Qué es una cesión absoluta?', '["Complete transfer of all policy rights permanently", "Temporary transfer", "Partial transfer", "No transfer"]', '["Transferencia completa de todos los derechos de la póliza permanentemente", "Transferencia temporal", "Transferencia parcial", "Sin transferencia"]', 0, 'An absolute assignment permanently transfers all ownership rights to the assignee.', 'Una cesión absoluta transfiere permanentemente todos los derechos de propiedad al cesionario.', true, '2026-01-14 23:01:15.566347', '2026-01-14 23:01:15.566347') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('48179d4f-9389-41ba-906d-9a862932072a', 'life_insurance', NULL, 'What is a key person life insurance policy?', '¿Qué es una póliza de seguro de vida de persona clave?', '["Insurance on all employees", "Insurance on a valuable employee or owner to protect the business", "Personal life insurance", "Group life insurance"]', '["Seguro para todos los empleados", "Seguro sobre un empleado valioso o propietario para proteger el negocio", "Seguro de vida personal", "Seguro de vida grupal"]', 1, 'Key person life insurance protects a business from financial loss if a key employee or owner dies, with the business as beneficiary.', 'El seguro de vida de persona clave protege a un negocio de pérdidas financieras si un empleado clave o propietario muere, con el negocio como beneficiario.', true, '2026-01-14 23:06:37.527264', '2026-01-14 23:06:37.527264') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4a5b1e5f-0d8a-435c-8fd5-59f74fde1842', 'life_insurance', NULL, 'What is a deferred annuity?', '¿Qué es una anualidad diferida?', '["An annuity where payments begin at a future date", "An immediate annuity", "Life insurance", "Health insurance"]', '["Una anualidad donde los pagos comienzan en una fecha futura", "Una anualidad inmediata", "Seguro de vida", "Seguro de salud"]', 0, 'A deferred annuity accumulates value during the accumulation phase and begins paying out at a later date, often at retirement.', 'Una anualidad diferida acumula valor durante la fase de acumulación y comienza a pagar en una fecha posterior, a menudo en la jubilación.', true, '2026-01-14 18:28:35.667584', '2026-01-14 18:28:35.667584') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4aa6a928-25c6-4de3-9852-d9255bae1b18', 'life_insurance', NULL, 'What is a non-participating policy?', '¿Qué es una póliza no participante?', '["A policy that does not pay dividends", "A policy that pays dividends", "A term policy", "A variable policy"]', '["Una póliza que no paga dividendos", "Una póliza que paga dividendos", "Una póliza a término", "Una póliza variable"]', 0, 'A non-participating policy does not share in the insurer''s surplus and pays no dividends.', 'Una póliza no participante no comparte el excedente del asegurador y no paga dividendos.', true, '2026-01-14 23:01:15.649947', '2026-01-14 23:01:15.649947') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('4f1982e0-90a2-4fcf-a012-b77f113c02ad', 'life_insurance', NULL, 'What form must be completed in Texas when replacing a life insurance policy?', '¿Qué formulario debe completarse en Texas al reemplazar una póliza de seguro de vida?', '["A replacement notice form", "No form is required", "A health questionnaire", "A tax form"]', '["Un formulario de aviso de reemplazo", "No se requiere formulario", "Un cuestionario de salud", "Un formulario de impuestos"]', 0, 'Texas requires specific disclosure forms when replacing life insurance policies to protect consumers.', 'Texas requiere formularios de divulgación específicos al reemplazar pólizas de seguro de vida para proteger a los consumidores.', true, '2026-01-14 22:54:57.211746', '2026-01-14 22:54:57.211746') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('50901347-8098-4eea-baa5-7627be71ed4b', 'life_insurance', NULL, 'What is a collateral assignment?', '¿Qué es una cesión colateral?', '["Temporary transfer of policy rights as security for a loan", "Permanent transfer", "Beneficiary change", "Policy cancellation"]', '["Transferencia temporal de derechos de la póliza como garantía de un préstamo", "Transferencia permanente", "Cambio de beneficiario", "Cancelación de póliza"]', 0, 'A collateral assignment temporarily assigns policy rights to a lender as loan collateral.', 'Una cesión colateral asigna temporalmente derechos de la póliza a un prestamista como garantía de préstamo.', true, '2026-01-14 23:01:15.571006', '2026-01-14 23:01:15.571006') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5100aa05-f0d9-4ab6-8eb0-a601196dd308', 'life_insurance', NULL, 'What is stranger-originated life insurance (STOLI)?', '¿Qué es el seguro de vida originado por extraños (STOLI)?', '["Life insurance purchased by investors with no insurable interest on the insured", "Standard life insurance", "Group insurance", "Term insurance"]', '["Seguro de vida comprado por inversores sin interés asegurable en el asegurado", "Seguro de vida estándar", "Seguro grupal", "Seguro a término"]', 0, 'STOLI involves third-party investors purchasing life insurance on individuals, which is generally prohibited.', 'STOLI involucra a inversores terceros comprando seguro de vida sobre individuos, lo cual generalmente está prohibido.', true, '2026-01-14 23:01:15.7322', '2026-01-14 23:01:15.7322') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('53446db7-877c-476b-a617-7716cce03de0', 'life_insurance', NULL, 'What is needs-based selling?', '¿Qué es la venta basada en necesidades?', '["Recommending coverage based on the client''s specific financial needs", "Selling any available product", "High-pressure sales", "Cold calling"]', '["Recomendar cobertura basada en las necesidades financieras específicas del cliente", "Vender cualquier producto disponible", "Ventas de alta presión", "Llamadas en frío"]', 0, 'Needs-based selling analyzes a client''s financial situation to recommend appropriate coverage amounts and types.', 'La venta basada en necesidades analiza la situación financiera de un cliente para recomendar montos y tipos de cobertura apropiados.', true, '2026-01-14 23:01:15.717756', '2026-01-14 23:01:15.717756') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('53923857-22ba-4283-8eb2-e45e2878513a', 'life_insurance', NULL, 'What is the purpose of the life insurance policy''s entire contract provision?', '¿Cuál es el propósito de la disposición del contrato completo de la póliza de seguro de vida?', '["To allow changes at any time", "To ensure all terms are in the policy and application", "To reduce premiums", "To eliminate the beneficiary"]', '["Permitir cambios en cualquier momento", "Asegurar que todos los términos estén en la póliza y la solicitud", "Reducir las primas", "Eliminar al beneficiario"]', 1, 'The entire contract provision ensures that the policy and attached application constitute the complete agreement between the insurer and policyholder.', 'La disposición del contrato completo asegura que la póliza y la solicitud adjunta constituyan el acuerdo completo entre el asegurador y el titular de la póliza.', true, '2026-01-14 23:06:37.483937', '2026-01-14 23:06:37.483937') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('548a3a54-abe8-418a-a00e-98c1910707e4', 'life_insurance', NULL, 'What is the tax treatment of policy loans?', '¿Cuál es el tratamiento fiscal de los préstamos de póliza?', '["Policy loans are not taxable if the policy remains in force", "Fully taxable", "Partially taxable", "Subject to capital gains tax"]', '["Los préstamos de póliza no son gravables si la póliza permanece en vigor", "Totalmente gravables", "Parcialmente gravables", "Sujetos a impuesto de ganancias de capital"]', 0, 'Policy loans are not considered taxable income as long as the policy remains in force.', 'Los préstamos de póliza no se consideran ingreso gravable mientras la póliza permanezca en vigor.', true, '2026-01-14 22:54:57.476911', '2026-01-14 22:54:57.476911') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('55d4b07c-e475-469f-95d2-3bce2c964f37', 'life_insurance', NULL, 'What is decreasing term life insurance?', '¿Qué es el seguro de vida a término decreciente?', '["Term insurance where the death benefit decreases over time", "Increasing coverage", "Level coverage", "Permanent coverage"]', '["Seguro a término donde el beneficio por muerte disminuye con el tiempo", "Cobertura creciente", "Cobertura nivelada", "Cobertura permanente"]', 0, 'Decreasing term has a death benefit that declines, often used to cover a decreasing debt like a mortgage.', 'El término decreciente tiene un beneficio por muerte que disminuye, a menudo usado para cubrir una deuda decreciente como una hipoteca.', true, '2026-01-14 22:54:57.265608', '2026-01-14 22:54:57.265608') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('597848be-a4f0-4a6a-997a-6d130d624487', 'life_insurance', NULL, 'What is the death benefit guarantee in a variable annuity?', '¿Qué es la garantía de beneficio por muerte en una anualidad variable?', '["Guarantees beneficiaries receive at least the amount invested if the annuitant dies during accumulation", "No guarantee", "Full market value only", "Double the investment"]', '["Garantiza que los beneficiarios reciban al menos el monto invertido si el beneficiario fallece durante la acumulación", "Sin garantía", "Solo valor de mercado completo", "El doble de la inversión"]', 0, 'The death benefit guarantee ensures beneficiaries receive at least the principal invested, regardless of market performance.', 'La garantía de beneficio por muerte asegura que los beneficiarios reciban al menos el capital invertido, independientemente del rendimiento del mercado.', true, '2026-01-14 23:01:15.772164', '2026-01-14 23:01:15.772164') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('59d144a6-acc7-4f67-b9b1-ff2590c23dd2', 'life_insurance', NULL, 'What is universal life insurance?', '¿Qué es el seguro de vida universal?', '["Permanent life insurance with flexible premiums and death benefits", "Term life insurance", "Whole life insurance", "Group life insurance"]', '["Seguro de vida permanente con primas y beneficios por muerte flexibles", "Seguro de vida temporal", "Seguro de vida entera", "Seguro de vida grupal"]', 0, 'Universal life is a type of permanent life insurance offering flexibility in premium payments and death benefit amounts.', 'El seguro de vida universal es un tipo de seguro de vida permanente que ofrece flexibilidad en pagos de primas y montos de beneficio por muerte.', true, '2026-01-14 18:28:35.63997', '2026-01-14 18:28:35.63997') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5a5e1954-50ce-468b-8110-cab1e24858c8', 'life_insurance', NULL, 'What is a Modified Endowment Contract (MEC) in life insurance?', '¿Qué es un Contrato de Dotación Modificado (MEC) en seguros de vida?', '["A policy with reduced benefits", "A policy that fails the 7-pay test and has different tax treatment", "A term life policy", "A policy without cash value"]', '["Una póliza con beneficios reducidos", "Una póliza que no pasa la prueba de 7 pagos y tiene un tratamiento fiscal diferente", "Una póliza de vida a término", "Una póliza sin valor en efectivo"]', 1, 'A MEC is a life insurance policy that is funded too quickly (fails the 7-pay test) and receives less favorable tax treatment on distributions.', 'Un MEC es una póliza de seguro de vida que se financia demasiado rápido (no pasa la prueba de 7 pagos) y recibe un tratamiento fiscal menos favorable en las distribuciones.', true, '2026-01-14 23:06:37.478538', '2026-01-14 23:06:37.478538') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5a74d8aa-309d-4e46-84c9-f94a1b363213', 'life_insurance', NULL, 'What is key person life insurance?', '¿Qué es el seguro de vida de persona clave?', '["Insurance on a key employee to protect the business from financial loss upon their death", "Personal insurance", "Health insurance", "Property insurance"]', '["Seguro sobre un empleado clave para proteger al negocio de pérdida financiera al fallecer", "Seguro personal", "Seguro de salud", "Seguro de propiedad"]', 0, 'Key person insurance protects a business from financial loss if a key employee dies.', 'El seguro de persona clave protege a un negocio de pérdida financiera si un empleado clave fallece.', true, '2026-01-14 22:54:57.484807', '2026-01-14 22:54:57.484807') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5cfc5310-2ab6-4f45-8154-abcb861da599', 'life_insurance', NULL, 'What is an equity-indexed annuity?', '¿Qué es una anualidad indexada a la renta variable?', '["A fixed annuity with no market participation", "An annuity with returns linked to a market index with downside protection", "A variable annuity", "A term annuity"]', '["Una anualidad fija sin participación en el mercado", "Una anualidad con rendimientos vinculados a un índice de mercado con protección contra pérdidas", "Una anualidad variable", "Una anualidad a término"]', 1, 'An equity-indexed annuity provides returns based on a market index while protecting against market losses with a minimum guaranteed rate.', 'Una anualidad indexada a la renta variable proporciona rendimientos basados en un índice de mercado mientras protege contra pérdidas del mercado con una tasa mínima garantizada.', true, '2026-01-14 23:06:37.592111', '2026-01-14 23:06:37.592111') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5f27403c-d92d-4bf5-b282-4158f189a57c', 'life_insurance', NULL, 'What is a policy surrender?', '¿Qué es un rescate de póliza?', '["Canceling a policy and receiving the cash surrender value", "Renewing a policy", "Changing beneficiaries", "Adding riders"]', '["Cancelar una póliza y recibir el valor de rescate en efectivo", "Renovar una póliza", "Cambiar beneficiarios", "Agregar anexos"]', 0, 'Surrendering a policy means terminating it and receiving the accumulated cash value minus any surrender charges.', 'Rescatar una póliza significa terminarla y recibir el valor en efectivo acumulado menos cualquier cargo por rescate.', true, '2026-01-14 22:54:57.421265', '2026-01-14 22:54:57.421265') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('5fc8a15d-cdcb-437c-a061-9398d25379f8', 'life_insurance', NULL, 'What is the transfer for value rule?', '¿Qué es la regla de transferencia por valor?', '["If a policy is sold for value, death benefits may become taxable", "Benefits are always tax-free", "Premium payments are taxed", "No tax implications"]', '["Si una póliza se vende por valor, los beneficios por muerte pueden volverse gravables", "Los beneficios siempre son libres de impuestos", "Los pagos de primas son gravados", "Sin implicaciones fiscales"]', 0, 'Under the transfer for value rule, if a policy is sold, death benefits above the buyer''s cost may be taxable.', 'Bajo la regla de transferencia por valor, si una póliza se vende, los beneficios por muerte por encima del costo del comprador pueden ser gravables.', true, '2026-01-14 23:01:15.746773', '2026-01-14 23:01:15.746773') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('60c44516-a9ab-45c7-8409-e808e6ff558b', 'life_insurance', NULL, 'What is the main difference between term life and whole life insurance?', '¿Cuál es la diferencia principal entre el seguro de vida a plazo y el seguro de vida entera?', '["Term life is more expensive", "Term life provides coverage for a specific period, while whole life provides lifetime coverage with cash value", "Whole life has no death benefit", "There is no difference"]', '["El seguro a plazo es más caro", "El seguro a plazo proporciona cobertura por un período específico, mientras que el seguro de vida entera proporciona cobertura de por vida con valor en efectivo", "El seguro de vida entera no tiene beneficio por fallecimiento", "No hay diferencia"]', 1, 'Term life insurance provides coverage for a set period (10, 20, or 30 years), while whole life insurance provides lifetime coverage and builds cash value over time.', 'El seguro de vida a plazo proporciona cobertura por un período determinado (10, 20 o 30 años), mientras que el seguro de vida entera proporciona cobertura de por vida y acumula valor en efectivo con el tiempo.', true, '2026-01-14 16:50:01.900231', '2026-01-14 16:50:01.900231') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6297f28d-acd6-4cd8-bb72-0801c9912275', 'life_insurance', NULL, 'What is a joint life insurance policy?', '¿Qué es una póliza de seguro de vida conjunta?', '["A policy on one person", "A policy that covers two or more people under one contract", "A term policy only", "A group policy"]', '["Una póliza sobre una persona", "Una póliza que cubre a dos o más personas bajo un contrato", "Solo una póliza a término", "Una póliza grupal"]', 1, 'A joint life insurance policy covers two or more people under a single policy and may pay upon the first or second death.', 'Una póliza de seguro de vida conjunta cubre a dos o más personas bajo una sola póliza y puede pagar al primer o segundo fallecimiento.', true, '2026-01-14 23:06:37.56981', '2026-01-14 23:06:37.56981') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('638943d3-21b2-41b7-bdce-b384e04a4000', 'life_insurance', NULL, 'What is insurable interest in life insurance?', '¿Qué es el interés asegurable en el seguro de vida?', '["A financial stake in the continued life of the insured", "Interest earned on premiums", "The cash value", "The death benefit"]', '["Una participación financiera en la vida continuada del asegurado", "Interés ganado sobre primas", "El valor en efectivo", "El beneficio por muerte"]', 0, 'Insurable interest means the policy owner must have a financial or emotional stake in the insured''s continued life.', 'El interés asegurable significa que el propietario de la póliza debe tener una participación financiera o emocional en la vida continuada del asegurado.', true, '2026-01-14 22:54:57.382459', '2026-01-14 22:54:57.382459') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('651a3933-2bed-4afb-8ad1-1de261d58af5', 'life_insurance', NULL, 'What is a deferred annuity?', '¿Qué es una anualidad diferida?', '["An annuity that pays immediately", "An annuity where payouts begin at a future date", "A term annuity", "An annuity with no cash value"]', '["Una anualidad que paga inmediatamente", "Una anualidad donde los pagos comienzan en una fecha futura", "Una anualidad a término", "Una anualidad sin valor en efectivo"]', 1, 'A deferred annuity postpones the payout phase to a future date, allowing funds to accumulate during the accumulation period.', 'Una anualidad diferida pospone la fase de pago a una fecha futura, permitiendo que los fondos se acumulen durante el período de acumulación.', true, '2026-01-14 23:06:37.630809', '2026-01-14 23:06:37.630809') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6583d687-c3c5-4755-be0d-01effd77c0b4', 'life_insurance', NULL, 'What is a flexible premium annuity?', '¿Qué es una anualidad de prima flexible?', '["An annuity that allows varying premium payments over time", "Fixed premium amounts", "Single premium only", "No premiums"]', '["Una anualidad que permite pagos de prima variables con el tiempo", "Montos de prima fijos", "Solo prima única", "Sin primas"]', 0, 'Flexible premium annuities allow the owner to make varying premium payments over time.', 'Las anualidades de prima flexible permiten al propietario hacer pagos de prima variables con el tiempo.', true, '2026-01-14 22:54:57.442671', '2026-01-14 22:54:57.442671') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('68c94851-5587-49a5-9111-658e3886014a', 'life_insurance', NULL, 'What is a premium in life insurance?', '¿Qué es una prima en el seguro de vida?', '["The payment made to keep the policy in force", "The death benefit", "The cash value", "The beneficiary amount"]', '["El pago hecho para mantener la póliza en vigor", "El beneficio por muerte", "El valor en efectivo", "El monto del beneficiario"]', 0, 'A premium is the periodic payment made to the insurance company to maintain coverage.', 'Una prima es el pago periódico hecho a la compañía de seguros para mantener la cobertura.', true, '2026-01-14 22:54:57.258075', '2026-01-14 22:54:57.258075') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6b2142db-f297-4ced-814f-ae2d3a3e9f01', 'life_insurance', NULL, 'What is industrial life insurance?', '¿Qué es el seguro de vida industrial?', '["Small face amount policies with premiums collected weekly at the home", "Large policies", "Group insurance", "Variable insurance"]', '["Pólizas de monto nominal pequeño con primas cobradas semanalmente en el hogar", "Pólizas grandes", "Seguro grupal", "Seguro variable"]', 0, 'Industrial (debit) life insurance has small face amounts with premiums collected weekly at the policyholder''s home.', 'El seguro de vida industrial (débito) tiene montos nominales pequeños con primas cobradas semanalmente en el hogar del asegurado.', true, '2026-01-14 23:01:15.68995', '2026-01-14 23:01:15.68995') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6b426efa-dd43-49b9-a268-49717025648f', 'life_insurance', NULL, 'What is a term conversion rider?', '¿Qué es un anexo de conversión a término?', '["Allows converting term insurance to permanent insurance without proof of insurability", "Only permanent to term", "No conversion allowed", "Requires medical exam"]', '["Permite convertir seguro a término a seguro permanente sin prueba de asegurabilidad", "Solo permanente a término", "No se permite conversión", "Requiere examen médico"]', 0, 'The term conversion rider allows converting a term policy to permanent coverage without medical underwriting.', 'El anexo de conversión a término permite convertir una póliza a término a cobertura permanente sin suscripción médica.', true, '2026-01-14 23:01:15.626252', '2026-01-14 23:01:15.626252') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6d8c9833-425e-4c51-b331-a2f21ed14fb8', 'life_insurance', NULL, 'What is the purpose of the automatic premium loan provision?', '¿Cuál es el propósito de la disposición de préstamo automático de prima?', '["To cancel the policy", "To prevent lapse by using cash value to pay overdue premiums", "To increase the death benefit", "To pay dividends"]', '["Cancelar la póliza", "Prevenir el vencimiento usando el valor en efectivo para pagar primas vencidas", "Aumentar el beneficio por muerte", "Pagar dividendos"]', 1, 'The automatic premium loan provision prevents policy lapse by automatically using the cash value to pay any unpaid premiums.', 'La disposición de préstamo automático de prima previene el vencimiento de la póliza utilizando automáticamente el valor en efectivo para pagar cualquier prima no pagada.', true, '2026-01-14 23:06:37.556438', '2026-01-14 23:06:37.556438') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6ddb95af-d4d9-4b68-b445-5d0323fbfec2', 'life_insurance', NULL, 'What is a graded death benefit?', '¿Qué es un beneficio por muerte graduado?', '["A death benefit that increases over time, often used in guaranteed issue policies", "Full benefit immediately", "Decreasing benefit", "No death benefit"]', '["Un beneficio por muerte que aumenta con el tiempo, a menudo usado en pólizas de emisión garantizada", "Beneficio completo inmediatamente", "Beneficio decreciente", "Sin beneficio por muerte"]', 0, 'Graded death benefits start low and increase over the first few years, common in guaranteed issue products.', 'Los beneficios por muerte graduados comienzan bajos y aumentan durante los primeros años, común en productos de emisión garantizada.', true, '2026-01-14 23:01:15.675216', '2026-01-14 23:01:15.675216') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6e503837-2960-4c80-8bfb-6c4a4c0e3770', 'life_insurance', NULL, 'What is the purpose of the life insurance policy''s assignment provision?', '¿Cuál es el propósito de la disposición de cesión de la póliza de seguro de vida?', '["To prevent policy transfer", "To allow the policyholder to transfer ownership rights to another party", "To cancel the policy", "To reduce premiums"]', '["Prevenir la transferencia de la póliza", "Permitir que el titular de la póliza transfiera los derechos de propiedad a otra parte", "Cancelar la póliza", "Reducir las primas"]', 1, 'The assignment provision allows the policyholder to transfer ownership or rights in the policy to another party, such as for collateral.', 'La disposición de cesión permite al titular de la póliza transferir la propiedad o los derechos de la póliza a otra parte, como para garantía.', true, '2026-01-14 23:06:37.625278', '2026-01-14 23:06:37.625278') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6effe423-e39f-4d31-8e1a-8c3508d0f9cf', 'life_insurance', NULL, 'What is an unfair trade practice in insurance?', '¿Qué es una práctica comercial injusta en seguros?', '["Any deceptive or dishonest practice that violates insurance laws", "Offering discounts", "Selling multiple policies", "Providing good service"]', '["Cualquier práctica engañosa o deshonesta que viole las leyes de seguros", "Ofrecer descuentos", "Vender múltiples pólizas", "Proporcionar buen servicio"]', 0, 'Unfair trade practices include misrepresentation, twisting, rebating, and other deceptive activities.', 'Las prácticas comerciales injustas incluyen tergiversación, twisting, rebating y otras actividades engañosas.', true, '2026-01-14 22:54:57.214785', '2026-01-14 22:54:57.214785') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6f1fa4f8-7748-42fe-891c-cbcb5ad3408e', 'life_insurance', NULL, 'What is the war exclusion?', '¿Qué es la exclusión de guerra?', '["Excludes death benefits for death caused by war or military action", "Covers war deaths", "Increases war coverage", "No war clause exists"]', '["Excluye beneficios por muerte por muerte causada por guerra o acción militar", "Cubre muertes de guerra", "Aumenta cobertura de guerra", "No existe cláusula de guerra"]', 0, 'The war exclusion excludes coverage for deaths resulting from war or acts of war.', 'La exclusión de guerra excluye cobertura por muertes resultantes de guerra o actos de guerra.', true, '2026-01-14 23:01:15.592158', '2026-01-14 23:01:15.592158') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7078b814-11de-446b-aac4-69a3b47960a1', 'life_insurance', NULL, 'Under Texas law, how long does a life insurance company have to pay a death claim after receiving proof of loss?', 'Según la ley de Texas, ¿cuánto tiempo tiene una compañía de seguros de vida para pagar un reclamo por muerte después de recibir la prueba de pérdida?', '["15 days", "30 days", "60 days", "90 days"]', '["15 días", "30 días", "60 días", "90 días"]', 2, 'Texas law requires life insurance companies to pay death claims within 60 days after receiving satisfactory proof of loss.', 'La ley de Texas requiere que las compañías de seguros de vida paguen los reclamos por muerte dentro de los 60 días posteriores a recibir la prueba de pérdida satisfactoria.', true, '2026-01-14 23:06:37.513147', '2026-01-14 23:06:37.513147') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('70e0487d-ca65-45af-9e4c-c7d53d196ab2', 'life_insurance', NULL, 'What is the conversion privilege in group life insurance?', '¿Qué es el privilegio de conversión en el seguro de vida grupal?', '["The right to convert group coverage to an individual policy without proof of insurability", "Increasing group coverage", "Changing beneficiaries", "Canceling coverage"]', '["El derecho de convertir cobertura grupal a una póliza individual sin prueba de asegurabilidad", "Aumentar cobertura grupal", "Cambiar beneficiarios", "Cancelar cobertura"]', 0, 'Conversion privilege allows employees leaving a group to obtain individual coverage without medical underwriting.', 'El privilegio de conversión permite a los empleados que dejan un grupo obtener cobertura individual sin suscripción médica.', true, '2026-01-14 22:54:57.468895', '2026-01-14 22:54:57.468895') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7114d777-10c6-42b0-9d5d-4168eaaff30e', 'life_insurance', NULL, 'What is the minimum age to obtain a Texas life insurance license?', '¿Cuál es la edad mínima para obtener una licencia de seguro de vida de Texas?', '["18 years old", "21 years old", "16 years old", "25 years old"]', '["18 años", "21 años", "16 años", "25 años"]', 0, 'Applicants must be at least 18 years old to obtain a Texas insurance license.', 'Los solicitantes deben tener al menos 18 años para obtener una licencia de seguros de Texas.', true, '2026-01-14 22:54:57.198624', '2026-01-14 22:54:57.198624') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('72ad4098-a339-4502-974f-e52d5f778e84', 'life_insurance', NULL, 'What is the surrender charge in an annuity?', '¿Qué es el cargo por rescate en una anualidad?', '["A fee charged for early withdrawal from the annuity", "A premium payment", "An interest payment", "A death benefit"]', '["Una tarifa cobrada por retiro anticipado de la anualidad", "Un pago de prima", "Un pago de interés", "Un beneficio por muerte"]', 0, 'Surrender charges are fees deducted if you withdraw from or surrender an annuity during the surrender period.', 'Los cargos por rescate son tarifas deducidas si se retira o rescata una anualidad durante el período de rescate.', true, '2026-01-14 23:01:15.768515', '2026-01-14 23:01:15.768515') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('72c7634f-8a90-4959-af60-4f6af984723b', 'life_insurance', NULL, 'What is the minimum grace period for life insurance premiums in Texas?', '¿Cuál es el período de gracia mínimo para las primas de seguro de vida en Texas?', '["7 days", "15 days", "30 days", "60 days"]', '["7 días", "15 días", "30 días", "60 días"]', 2, 'Texas requires a minimum 30-day grace period for life insurance premium payments after the due date.', 'Texas requiere un período de gracia mínimo de 30 días para los pagos de primas de seguro de vida después de la fecha de vencimiento.', true, '2026-01-14 23:06:37.6223', '2026-01-14 23:06:37.6223') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7450d9cf-3275-471e-bccc-7d50cd7ec48f', 'life_insurance', NULL, 'What is the incontestability clause?', '¿Qué es la cláusula de incontestabilidad?', '["After the contestability period, the insurer cannot deny claims based on misstatements in the application", "The insurer can always contest", "No claims can be denied", "The policy automatically renews"]', '["Después del período de contestabilidad, el asegurador no puede negar reclamos basados en declaraciones falsas en la solicitud", "El asegurador siempre puede contestar", "No se pueden negar reclamos", "La póliza se renueva automáticamente"]', 0, 'Once the contestability period expires, the insurer cannot void the policy for misrepresentation except for fraud.', 'Una vez que expira el período de contestabilidad, el asegurador no puede anular la póliza por tergiversación excepto por fraude.', true, '2026-01-14 22:54:57.309784', '2026-01-14 22:54:57.309784') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('770b5bf8-5cf8-4ed4-8581-a2a020062966', 'life_insurance', NULL, 'In Texas, what is a viatical settlement?', 'En Texas, ¿qué es un acuerdo viático?', '["A loan against the policy", "Sale of a life insurance policy by a terminally ill person", "A type of annuity", "A dividend option"]', '["Un préstamo contra la póliza", "Venta de una póliza de seguro de vida por una persona con enfermedad terminal", "Un tipo de anualidad", "Una opción de dividendos"]', 1, 'A viatical settlement is the sale of a life insurance policy by a terminally ill insured to a third party for less than the death benefit.', 'Un acuerdo viático es la venta de una póliza de seguro de vida por un asegurado con enfermedad terminal a un tercero por menos del beneficio por muerte.', true, '2026-01-14 23:06:37.453696', '2026-01-14 23:06:37.453696') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('78eecaf6-975b-42f4-acab-d8d953a4a036', 'life_insurance', NULL, 'What is replacement in life insurance?', '¿Qué es el reemplazo en seguro de vida?', '["Using the values of an existing policy to purchase a new policy", "Buying additional coverage", "Canceling a policy", "Changing beneficiaries"]', '["Usar los valores de una póliza existente para comprar una nueva póliza", "Comprar cobertura adicional", "Cancelar una póliza", "Cambiar beneficiarios"]', 0, 'Replacement occurs when a new policy is purchased and an existing policy is surrendered, lapsed, or changed.', 'El reemplazo ocurre cuando se compra una nueva póliza y una póliza existente se rescata, caduca o cambia.', true, '2026-01-14 22:54:57.208666', '2026-01-14 22:54:57.208666') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7ab0f7a0-4bbc-4a99-b556-1a23087439ed', 'life_insurance', NULL, 'What is the three-year rule for life insurance and estate taxes?', '¿Qué es la regla de tres años para seguro de vida e impuestos patrimoniales?', '["Policies transferred within 3 years of death may be included in the estate", "No time limit", "1-year rule", "5-year rule"]', '["Las pólizas transferidas dentro de 3 años de la muerte pueden incluirse en el patrimonio", "Sin límite de tiempo", "Regla de 1 año", "Regla de 5 años"]', 0, 'If a policy is transferred to an ILIT within 3 years of death, it may still be included in the taxable estate.', 'Si una póliza se transfiere a un ILIT dentro de 3 años de la muerte, aún puede incluirse en el patrimonio gravable.', true, '2026-01-14 23:01:15.753837', '2026-01-14 23:01:15.753837') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7d5742bb-b07f-42b7-b4df-ab9bfdec43ff', 'life_insurance', NULL, 'What is the difference between current assumption whole life and traditional whole life?', '¿Cuál es la diferencia entre vida entera de suposición actual y vida entera tradicional?', '["No difference", "Current assumption has non-guaranteed elements that can change", "Traditional has variable investments", "Current assumption has no cash value"]', '["Sin diferencia", "La suposición actual tiene elementos no garantizados que pueden cambiar", "La tradicional tiene inversiones variables", "La suposición actual no tiene valor en efectivo"]', 1, 'Current assumption whole life has non-guaranteed elements like interest rates and mortality charges that can be adjusted by the insurer.', 'La vida entera de suposición actual tiene elementos no garantizados como tasas de interés y cargos de mortalidad que pueden ser ajustados por el asegurador.', true, '2026-01-14 23:06:37.578126', '2026-01-14 23:06:37.578126') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7dea9d75-9f8c-4d87-a268-0fac5b86faa7', 'life_insurance', NULL, 'What is survivorship (second-to-die) life insurance?', '¿Qué es el seguro de vida de supervivencia (segundo en morir)?', '["A policy that pays the death benefit when the second of two insureds dies", "Pays on first death", "Individual policy", "Term insurance"]', '["Una póliza que paga el beneficio por muerte cuando el segundo de dos asegurados fallece", "Paga en la primera muerte", "Póliza individual", "Seguro a término"]', 0, 'Survivorship insurance covers two lives but pays the death benefit only after both insureds have died.', 'El seguro de supervivencia cubre dos vidas pero paga el beneficio por muerte solo después de que ambos asegurados hayan fallecido.', true, '2026-01-14 23:01:15.656762', '2026-01-14 23:01:15.656762') ON CONFLICT (id) DO NOTHING;
